fn streamer(steps: Vec<Step>, serial_retry: bool) -> TestStream {
    let diagnostics = Diagnostics::new("memory", RX_BUFFER, serial_retry);
    let mut stream = Streamer::new(
        MemoryPort { steps: steps.into(), ..MemoryPort::default() },
        RecordingEvents::default(),
        Arc::new(AtomicBool::new(false)),
        Protocol::grbl(false),
    ).with_diagnostics(diagnostics, serial_retry);
    // Suppress unsolicited polls without sleeping or changing the environment.
    stream.last_poll = Instant::now() + Duration::from_secs(3600);
    stream
}

fn start_job(stream: &mut TestStream, lines: &[&str]) {
    stream.handle(Cmd::Job(lines.iter().map(|line| (*line).into()).collect())).unwrap();
}

#[test]
fn partial_zero_remaining_is_exact_and_commits_only_after_lf() {
    let mut s = streamer(vec![Step::Accept(2), Step::Accept(0)], true);
    start_job(&mut s, &["G1 X7"]);
    s.pump().unwrap();
    assert_eq!(s.port.bytes, b"G1");
    assert_eq!(s.pending.as_ref().unwrap().offset, 2);
    assert_eq!(s.job.as_ref().unwrap().next, 0);
    assert!(s.inflight.is_empty());
    assert_eq!(s.inflight_bytes, 0);
    s.pump().unwrap();
    assert_eq!(s.port.bytes, b"G1 X7\n");
    assert_eq!(s.port.attempts, vec![b"G1 X7\n".to_vec(), b" X7\n".to_vec(), b" X7\n".to_vec()]);
    assert!(s.pending.is_none());
    assert_eq!(s.job.as_ref().unwrap().next, 1);
    assert_eq!(s.inflight.len(), 1);
    assert_eq!(s.inflight_bytes, 6);
}

