#[test]
fn serial_zero_and_transient_errors_recover_without_resending_prefix() {
    let mut s = streamer(vec![
        Step::Accept(1), Step::Accept(0), Step::Fail(ErrorKind::WouldBlock),
        Step::Fail(ErrorKind::TimedOut), Step::Fail(ErrorKind::Interrupted),
    ], true);
    start_job(&mut s, &["G21"]);
    for _ in 0..5 { s.pump().unwrap(); }
    assert_eq!(s.port.bytes, b"G21\n");
    assert_eq!(s.port.attempts.len(), 6);
    assert!(s.port.attempts[1..].iter().all(|bytes| bytes == b"21\n"));
    assert_eq!(s.job.as_ref().unwrap().next, 1);
    let snapshot = s.diagnostics.snapshot().unwrap();
    assert_eq!(snapshot.sent_lines, 1);
    assert_eq!(snapshot.events.iter().filter(|event| event.name == "write-retry").count(), 3);
}

