#[test]
fn stop_partial_line_sends_hold_then_delayed_reset_and_is_terminal() {
    let mut s = streamer(vec![Step::Accept(2), Step::Accept(0)], true);
    start_job(&mut s, &["G21", "G90"]);
    s.output().unwrap();
    s.handle(Cmd::Stop).unwrap();
    assert!(s.job.is_none());
    assert!(s.pending.is_none());
    assert!(!s.busy.load(Ordering::SeqCst));
    s.output().unwrap();
    assert_eq!(s.port.bytes, b"G2!");
    assert!(!s.close_after_stop);
    assert_eq!(s.controls.front().unwrap().kind, WriteKind::StopReset);
    assert!(s.controls.front().unwrap().not_before > Instant::now());
    s.output().unwrap();
    assert_eq!(s.port.bytes, b"G2!");
    s.handle(Cmd::Resume).unwrap();
    s.handle(Cmd::Job(vec!["G90".into()])).unwrap();
    s.handle(Cmd::Line("G90".into())).unwrap();
    s.controls.front_mut().unwrap().not_before = Instant::now() - Duration::from_secs(1);
    s.output().unwrap();
    assert_eq!(s.port.bytes, b"G2!\x18");
    assert!(s.close_after_stop);
    assert!(s.inflight.is_empty());
    assert_eq!(s.inflight_bytes, 0);
    assert!(s.queue.is_empty());
    assert_eq!(s.events.0.lock().unwrap().as_slice(), ["done:false"]);
}

