#[test]
fn close_command_ends_run_without_attempting_pending_suffix() {
    let mut s = streamer(vec![Step::Accept(2), Step::Accept(0)], true);
    start_job(&mut s, &["G21"]);
    s.output().unwrap();
    let events = s.events.clone();
    let busy = s.busy.clone();
    let diagnostics = s.diagnostics.clone();
    // Any further write would fail; Close must exit before pumping again.
    s.port.steps.push_back(Step::Fail(ErrorKind::BrokenPipe));
    let (tx, rx) = std::sync::mpsc::channel();
    tx.send(Cmd::Close).unwrap();
    s.run(rx);
    assert_eq!(events.0.lock().unwrap().as_slice(), ["done:false", "closed:false"]);
    assert!(!busy.load(Ordering::SeqCst));
    let snapshot = diagnostics.snapshot().unwrap();
    assert!(!snapshot.connected);
    assert!(snapshot.last_error.is_none());
    assert!(!snapshot.events.iter().any(|event| event.name == "write-failed"));
}

