#[test]
fn stalled_priority_control_preserves_its_own_offset_and_blocks_job_output() {
    let mut s = streamer(vec![Step::Accept(0), Step::Fail(ErrorKind::WouldBlock)], true);
    start_job(&mut s, &["G21"]);
    s.handle(Cmd::Realtime(b'?')).unwrap();
    for _ in 0..2 {
        s.pump().unwrap();
        assert!(s.port.bytes.is_empty());
        assert_eq!(s.controls.front().unwrap().offset, 0);
        assert_eq!(s.job.as_ref().unwrap().next, 0);
    }
    s.pump().unwrap();
    assert_eq!(s.port.bytes, b"?G21\n");
    assert_eq!(s.port.reads, 3);
    assert!(s.controls.is_empty());
}

#[test]
fn priority_control_deadline_reports_control_not_pending_job() {
    let mut s = streamer(vec![Step::Accept(1), Step::Accept(0)], true);
    start_job(&mut s, &["G21"]);
    s.output().unwrap();
    s.handle(Cmd::Realtime(b'?')).unwrap();
    s.controls.front_mut().unwrap().started = Some(Instant::now() - WRITE_DEADLINE - Duration::from_secs(1));
    let attempts = s.port.attempts.len();
    let error = s.output().unwrap_err();
    assert!(error.contains("kind=realtime"));
    assert!(error.contains("accepted=0/1"));
    assert_eq!(s.port.attempts.len(), attempts);
    assert_eq!(s.pending.as_ref().unwrap().offset, 1);
    assert_eq!(s.diagnostics.snapshot().unwrap().pending_kind, Some("realtime"));
}

#[test]
fn ack_for_previous_line_does_not_ack_partially_written_next_line() {
    let mut s = streamer(vec![Step::Accept(4), Step::Accept(2), Step::Accept(0)], true);
    start_job(&mut s, &["G21", "G90"]);
    s.output().unwrap();
    assert_eq!(s.port.bytes, b"G21\nG9");
    assert_eq!(s.inflight.len(), 1);
    assert_eq!(s.job.as_ref().unwrap().next, 1);
    s.on_bytes(b"ok\n");
    assert!(s.inflight.is_empty());
    assert_eq!(s.inflight_bytes, 0);
    assert_eq!(s.job.as_ref().unwrap().acked, 1);
    assert_eq!(s.pending.as_ref().unwrap().offset, 2);
    s.output().unwrap();
    assert_eq!(s.port.bytes, b"G21\nG90\n");
    assert_eq!(s.job.as_ref().unwrap().next, 2);
    assert_eq!(s.job.as_ref().unwrap().acked, 1);
    s.on_bytes(b"ok\n");
    assert_eq!(s.job.as_ref().unwrap().acked, 2);
    assert!(s.inflight.is_empty());
}
